// 改行が CR だけのファイル。行コメントは CR で終わり、次の行の using: を認めるlet injected = Int.random(in: 0..<10, // コメント    using: &generator)let nested = Int.random(in: 0..<length(of: 1, // コメント ) (    2), using: &generator)let labelled = Int.random(in: 0..<10, using // コメント    : &generator)// 行コメントの中の using: は引数ではない。using: のない呼び出しは検出するlet direct = Int.random(in: 0..<10) // expect: no_direct_randomlet commented = Int.random(in: 0..<10 // , using: &generator // expect: no_direct_random)